CREATE TABLE IF NOT EXISTS economic_capital_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), onboarding_id uuid NOT NULL, institution_id uuid, source_profile_id uuid, capital_type text, fit_score numeric(6,3) NOT NULL DEFAULT 0, fit_state text NOT NULL DEFAULT 'weak_fit', rationale text, strengths jsonb NOT NULL DEFAULT '[]'::jsonb, gaps jsonb NOT NULL DEFAULT '[]'::jsonb, next_actions jsonb NOT NULL DEFAULT '[]'::jsonb, assessed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(onboarding_id,institution_id,source_profile_id,capital_type))